//! Writes the prelude's generated folder, `neo-playwright-js/src/prelude/generated/`, from Rust's
//! op table (`Op::all()`, each op's `spec()`) and each described op's wire (`Op::wire()`). A
//! stale file is rewritten and the test fails, so the regenerated files are reviewed and
//! committed like any other change. ts-rs prints every type; this file only lays them out.
//!
//! ```text
//!  generated/
//!    ops.ts            OPS and OpName: every op's name, effect, target field and lifetime
//!    types/<Name>.ts   one file per named Rust type, as ts-rs prints it (imports, doc, declaration)
//!    common.ts         re-exports the types two or more families reach, once
//!    <family>.ts       per family (`Op::family`): re-exports its own types; <Family>Inputs and
//!                      <Family>Outputs; <FAMILY>_OPTION_KEYS; <FAMILY>_SEND, one typed sender
//!                      per op; the upstream check of each route row against `channels.d.ts`
//!    index.ts          GeneratedInputs, GeneratedOutputs, OPTION_KEYS and `send` over every family
//! ```
//!
//! One file per family, so two family changes in flight never edit the same generated text.
//! Every file in the folder is the generator's, but those in [`FOREIGN`]: one the layout no
//! longer writes is removed.

use std::collections::{BTreeMap, BTreeSet};
use std::error::Error;
use std::fmt::Write as _;
use std::path::{Path, PathBuf};
use std::{fs, io};

use neo_playwright::{
    Command, Op, OpLifetime, OpTarget, OpWire, OptionNesting, Upstream, WireType,
};
use neo_trace::Effect;

/// From this crate's manifest directory.
const GENERATED: &str = "../neo-playwright-js/src/prelude/generated";

/// Generated files by path, relative to the generated folder.
type Files = BTreeMap<PathBuf, String>;

/// Files in the folder that another generator owns, which this one neither writes nor removes:
/// the run envelope's types, from neo-server's `tests/envelope_generated.rs`.
const FOREIGN: &[&str] = &["envelope.ts"];

/// The header of every file this test writes; ts-rs's own files under `types/` carry its own.
const HEADER: &str = "\
// Generated by crates/neo-sdk/neo-playwright/tests/wire_generated.rs from Rust's op table and
// each family's route rows (`Op::wire()`). Do not edit: change the op's handler types or its
// route row in Rust, then run `cargo test -p neo-playwright --test wire_generated`, which
// rewrites this folder.
";

/// Upstream's generated protocol types at the pin, vendored byte for byte (`third_party`).
const CHANNELS: &str = "../../../../neo-playwright/third_party/playwright/packages/playwright-core/src/client/channels";

/// A TypeScript name a Rust type prints as an import instead of a derived shape
/// (`#[ts(type = "import('…').Name")]`). Allowed only where an example file both sides decode
/// keeps the Rust type and the imported declaration in step, or where the value is opaque to
/// Rust by design: nothing else compares the two.
struct Imported {
    /// The module as the generated file imports it, relative to `generated/types/`.
    module: &'static str,
    name: &'static str,
    /// The example file (from this crate's manifest directory) that holds the two together.
    checked_by: &'static str,
}

/// Every imported name the generated types print, each with its check. A family that imports
/// another probe or vendored type adds its row here, naming the file that checks it.
const IMPORTED: &[Imported] = &[
    Imported {
        module: "../../../probe/protocol",
        name: "SelectOption",
        checked_by: "tests/data/probe-protocol.json",
    },
    Imported {
        module: "../../../probe/protocol",
        name: "Rect",
        checked_by: "tests/data/probe-protocol.json",
    },
    Imported {
        module: "../../../probe/protocol",
        name: "Point",
        checked_by: "tests/data/probe-protocol.json",
    },
    Imported {
        module: "../../../probe/protocol",
        name: "Edit",
        checked_by: "tests/data/probe-protocol.json",
    },
    Imported {
        module: "../../../probe/protocol",
        name: "FilePayload",
        checked_by: "tests/data/probe-protocol.json",
    },
    Imported {
        module: "../../../probe/protocol",
        name: "SnapshotMode",
        checked_by: "tests/data/probe-protocol.json",
    },
    Imported {
        module: "../../../probe/protocol",
        name: "ExpectParams",
        checked_by: "tests/data/probe-protocol.json",
    },
    Imported {
        module: "../../../probe/protocol",
        name: "UrlPattern",
        checked_by: "tests/data/probe-protocol.json",
    },
    Imported {
        module: "../../vendored",
        name: "AriaSnapshotJSON",
        checked_by: "tests/data/snapshot-output.json",
    },
    // Rust passes the page's value through after holding it to the format's depth and shape;
    // the recorded values are what Rust writes back for each in-page value.
    Imported {
        module: "../../../../../neo-playwright/third_party/playwright/packages/isomorphic/utilityScriptSerializers",
        name: "SerializedValue",
        checked_by: "tests/data/in-page-values.json",
    },
    // The prelude's own parse of a selector; Rust keeps each chunk's JSON and reads only the
    // ref jumps, and the recorded prelude inputs decode in Rust.
    Imported {
        module: "../../vendored",
        name: "ParsedSelector",
        checked_by: "tests/data/wire-examples.json",
    },
];

/// One imported TypeScript name, as a generated file prints it.
#[derive(Debug, PartialEq, Eq, PartialOrd, Ord)]
struct Import {
    module: String,
    name: String,
}

/// Every `import('<module>').<Name>` in `text`, in order.
fn imports(text: &str) -> Vec<Import> {
    let mut found = Vec::new();
    for piece in text.split("import(").skip(1) {
        let Some((module, after)) = piece
            .strip_prefix(['\'', '"'])
            .and_then(|quoted| quoted.split_once(['\'', '"']))
        else {
            continue;
        };
        let Some(after) = after.strip_prefix(").") else {
            continue;
        };
        let name: String = after
            .chars()
            .take_while(|c| c.is_ascii_alphanumeric() || *c == '_' || *c == '$')
            .collect();
        found.push(Import {
            module: module.to_owned(),
            name,
        });
    }
    found
}

/// One named type of the whole layout, with the families whose ops reach it: one family's own
/// type is exported from its file, one reached by two or more from `common.ts`.
struct Reached<'w> {
    declaration: &'w WireType,
    families: BTreeSet<&'w str>,
}

/// One family's ops in registration order, with the wire of each one Rust describes.
struct Family {
    name: &'static str,
    ops: Vec<(&'static str, OpWire)>,
}

/// Every family in `Op::all()`'s order. A family whose ops are not described yet still gets its
/// (empty) file, so `index.ts` names the same files whichever families have moved.
fn families() -> Vec<Family> {
    let mut families: Vec<Family> = Vec::new();
    for op in Op::all() {
        let name = op.family();
        if !families.iter().any(|family| family.name == name) {
            families.push(Family {
                name,
                ops: Vec::new(),
            });
        }
        let family = families.iter_mut().find(|family| family.name == name);
        if let (Some(wire), Some(family)) = (op.wire(), family) {
            family.ops.push((op.spec().name, wire));
        }
    }
    families
}

/// `ops.ts`: today's `OPS` and `OpName`, in the shape Biome formats it (single quotes, no
/// semicolons, one expanded object per op).
fn ops_ts() -> Result<String, Box<dyn Error>> {
    let mut out = format!(
        "{HEADER}\n\
         /**\n \
         * Every operation the prelude can invoke, in Rust's registration order, with what the\n \
         * host's dispatcher knows about it: whether it may change the page, which input field\n \
         * holds the page handle, and whether it is prelude-owned background work.\n \
         */\n\
         export const OPS = {{\n"
    );
    for op in Op::all() {
        let spec = op.spec();
        let effect = match spec.effect {
            Effect::Read => "'read'",
            Effect::Write => "'write'",
        };
        let target = match spec.target {
            OpTarget::None => "null".to_owned(),
            OpTarget::Field(field) => format!("'{field}'"),
        };
        let lifetime = match spec.lifetime {
            OpLifetime::Operation => "'operation'",
            OpLifetime::Background => "'background'",
        };
        write!(
            out,
            "  '{}': {{\n    effect: {effect},\n    target: {target},\n    lifetime: {lifetime},\n  }},\n",
            spec.name
        )?;
    }
    out.push_str(
        "} as const\n\
         \n\
         /** A name `__neo.invoke` accepts for a Playwright operation. */\n\
         export type OpName = keyof typeof OPS\n",
    );
    Ok(out)
}

/// Lays out every generated file but `ops.ts`, or says what refuses to be laid out: two Rust
/// types printing under one TypeScript name, a type ts-rs could not print, an input or a result
/// typed as `unknown`.
fn render(families: &[Family]) -> Result<Files, Vec<String>> {
    let mut refusals = Vec::new();
    // Each named type once, with the families that reach it.
    let mut types: BTreeMap<&Path, Reached<'_>> = BTreeMap::new();
    for family in families {
        for (op, wire) in &family.ops {
            for (side, reference) in [("input", &wire.input), ("result", &wire.output)] {
                if is_untyped(reference) {
                    refusals.push(format!("{op}: its {side} prints as `{reference}`"));
                }
            }
            for named in &wire.types {
                let reached = types
                    .entry(named.file.as_path())
                    .or_insert_with(|| Reached {
                        declaration: named,
                        families: BTreeSet::new(),
                    });
                if reached.declaration.id != named.id {
                    refusals.push(format!(
                        "{} and {} both print as TypeScript `{}`; rename one with #[ts(rename)]",
                        reached.declaration.rust, named.rust, named.name
                    ));
                }
                reached.families.insert(family.name);
            }
        }
    }
    let mut files = Files::new();
    for (file, reached) in &types {
        match &reached.declaration.text {
            Ok(text) => {
                files.insert(Path::new("types").join(file), text.clone());
            }
            Err(error) => refusals.push(format!(
                "ts-rs cannot print {}: {error}",
                reached.declaration.rust
            )),
        }
    }
    if !refusals.is_empty() {
        return Err(refusals);
    }
    let shared: Vec<&WireType> = types
        .values()
        .filter(|reached| reached.families.len() > 1)
        .map(|reached| reached.declaration)
        .collect();
    files.insert("common.ts".into(), common_ts(&shared));
    for family in families {
        let own: Vec<&WireType> = types
            .values()
            .filter(|reached| reached.families.len() == 1 && reached.families.contains(family.name))
            .map(|reached| reached.declaration)
            .collect();
        let path = PathBuf::from(format!("{}.ts", family.name));
        files.insert(path, family_ts(family, &own, &types));
    }
    files.insert("index.ts".into(), index_ts(families));
    Ok(files)
}

/// A reference that types nothing: TypeScript's escape hatches, or ts-rs's name for
/// `serde_json::Value`.
fn is_untyped(reference: &str) -> bool {
    matches!(
        reference.trim_end_matches(" | null"),
        "unknown" | "any" | "JsonValue"
    )
}

/// The import path of a type's file from the generated folder: `./types/ClickInput`.
fn type_module(file: &Path) -> String {
    let file = file.with_extension("");
    format!("./types/{}", file.display())
}

fn common_ts(shared: &[&WireType]) -> String {
    let mut out = format!(
        "{HEADER}\n\
         // The named types two or more families reach, exported once here so `index.ts` exports\n\
         // each name from one module.\n"
    );
    if shared.is_empty() {
        out.push_str("export {}\n");
    }
    for named in shared {
        let _ = writeln!(
            out,
            "export type {{ {} }} from '{}'",
            named.name,
            type_module(&named.file)
        );
    }
    out
}

/// `word` with its first letter in upper case.
fn capitalized(word: &str) -> String {
    let mut chars = word.chars();
    chars.next().map_or_else(String::new, |first| {
        format!("{}{}", first.to_ascii_uppercase(), chars.as_str())
    })
}

/// `locator-handler` as `LocatorHandler`, for the family's type names.
fn pascal(family: &str) -> String {
    family.split('-').map(capitalized).collect()
}

/// `locator-handler` as `LOCATOR_HANDLER`, for the family's constants.
fn screaming(family: &str) -> String {
    family.replace('-', "_").to_ascii_uppercase()
}

/// `ElementHandle.click` as `ElementHandleClick`, the stem of upstream's `…Params`, `…Options`
/// and `…Result` types in `channels.d.ts`.
fn command_stem(command: &str) -> String {
    let (interface, method) = command.split_once('.').unwrap_or((command, ""));
    format!("{interface}{}", capitalized(method))
}

/// `locator.click` as `_locator_click`: one named alias per op, so a failing check's error line
/// names the op. Op names are letters, digits and dots (`ops.ts`'s test pins it).
fn alias(op: &str) -> String {
    format!("_{}", op.replace('.', "_"))
}

/// A TypeScript single-quoted string.
fn quoted(text: &str) -> String {
    format!("'{}'", text.replace('\\', "\\\\").replace('\'', "\\'"))
}

/// The keys of a deviation list as a TypeScript union, `never` when there are none.
fn union(keys: &[(&str, &str)]) -> String {
    if keys.is_empty() {
        return "never".to_owned();
    }
    let keys: Vec<String> = keys.iter().map(|(key, _)| quoted(key)).collect();
    keys.join(" | ")
}

/// One reason as a comment line; reasons are one line by convention.
fn reason(text: &str) -> String {
    text.split_whitespace().collect::<Vec<_>>().join(" ")
}

fn family_ts(family: &Family, own: &[&WireType], types: &BTreeMap<&Path, Reached<'_>>) -> String {
    let pascal = pascal(family.name);
    let screaming = screaming(family.name);
    let mut out = format!("{HEADER}\n");
    let checks = upstream_checks(family, &screaming);
    if !family.ops.is_empty() {
        for line in family_imports(family, &checks, types) {
            let _ = writeln!(out, "{line}");
        }
        out.push('\n');
    }
    for named in own {
        let _ = writeln!(
            out,
            "export type {{ {} }} from '{}'",
            named.name,
            type_module(&named.file)
        );
    }
    if !own.is_empty() {
        out.push('\n');
    }

    let _ = writeln!(
        out,
        "/** Each {} op's input, after the `call` header every op shares. */",
        family.name
    );
    write_map(
        &mut out,
        &format!("export type {pascal}Inputs ="),
        family,
        |wire| wire.input.clone(),
    );
    let _ = writeln!(out, "\n/** Each {} op's result. */", family.name);
    write_map(
        &mut out,
        &format!("export type {pascal}Outputs ="),
        family,
        |wire| wire.output.clone(),
    );

    let _ = writeln!(
        out,
        "\n/**\n * The script's option keys of each {} op that takes an `options` bag: the fields of its\n \
         * Rust options struct, for `pick`. Each command row's list is held to upstream's\n \
         * `<Command>Options` below, so a field the prelude computes is never forwarded from a script.\n */",
        family.name
    );
    let keyed: Vec<&(&str, OpWire)> = family
        .ops
        .iter()
        .filter(|(_, wire)| !wire.option_keys.is_empty())
        .collect();
    if keyed.is_empty() {
        let _ = writeln!(out, "export const {screaming}_OPTION_KEYS = {{}} as const");
    } else {
        let _ = writeln!(out, "export const {screaming}_OPTION_KEYS = {{");
        for (op, wire) in keyed {
            let keys: Vec<String> = wire.option_keys.iter().map(|key| quoted(key)).collect();
            let _ = writeln!(out, "  {}: [{}],", quoted(op), keys.join(", "));
        }
        out.push_str("} as const\n");
    }

    let _ = writeln!(
        out,
        "\n/**\n * One typed sender per {} op. A class passes its input as an object literal, so every\n \
         * field is checked against Rust's input type and the result is Rust's result type.\n */",
        family.name
    );
    if family.ops.is_empty() {
        let _ = writeln!(out, "export const {screaming}_SEND = {{}}");
    } else {
        let _ = writeln!(out, "export const {screaming}_SEND = {{");
        for (op, wire) in &family.ops {
            let _ = writeln!(
                out,
                "  {name}: (\n    site: CallSite,\n    call: CallHeader,\n    input: {input},\n    \
                 signal?: SignalLike,\n  ): Promise<{output}> => invoke({name}, site, call, input, signal),",
                name = quoted(op),
                input = wire.input,
                output = wire.output,
            );
        }
        out.push_str("}\n");
    }
    if !checks.lines.is_empty() {
        out.push_str(
            "\n// Each route row against Playwright's own protocol at the pin (upstream-check.ts): tsc\n\
             // names the op and every key that differs without a reason, or whose reason went stale.\n",
        );
        out.push_str(&checks.lines);
    }
    out
}

/// A described family's imports: what its senders and checks use, and each named type its maps
/// reference (from `types/`, whether the type is the family's own or shared).
fn family_imports(
    family: &Family,
    checks: &Checks,
    types: &BTreeMap<&Path, Reached<'_>>,
) -> Vec<String> {
    let mut imports = Vec::new();
    if checks.uses_channels {
        imports.push(format!("import type * as pw from '{CHANNELS}'"));
    }
    imports.push("import { invoke } from '../bridge'".to_owned());
    imports.push("import type { CallSite } from '../call-site'".to_owned());
    imports.push("import type { SignalLike } from '../signal'".to_owned());
    if !checks.helpers.is_empty() {
        let helpers: Vec<&str> = checks.helpers.iter().copied().collect();
        imports.push(format!(
            "import type {{ {} }} from '../upstream-check'",
            helpers.join(", ")
        ));
    }
    imports.push("import type { CallHeader } from '../wire'".to_owned());
    let referenced: BTreeSet<&str> = family
        .ops
        .iter()
        .flat_map(|(_, wire)| wire.references.iter().map(String::as_str))
        .collect();
    for named in types.values().map(|reached| reached.declaration) {
        if referenced.contains(named.name.as_str()) {
            imports.push(format!(
                "import type {{ {} }} from '{}'",
                named.name,
                type_module(&named.file)
            ));
        }
    }
    imports
}

/// `export type <Name> = { 'op': <ref> }`, or `{}` for a family with nothing described.
fn write_map(out: &mut String, head: &str, family: &Family, reference: impl Fn(&OpWire) -> String) {
    if family.ops.is_empty() {
        let _ = writeln!(out, "{head} {{}}");
        return;
    }
    let _ = writeln!(out, "{head} {{");
    for (op, wire) in &family.ops {
        let _ = writeln!(out, "  {}: {}", quoted(op), reference(wire));
    }
    out.push_str("}\n");
}

/// The upstream assertions of one family, and what they import.
struct Checks {
    lines: String,
    helpers: BTreeSet<&'static str>,
    uses_channels: bool,
}

fn upstream_checks(family: &Family, screaming: &str) -> Checks {
    let mut checks = Checks {
        lines: String::new(),
        helpers: BTreeSet::new(),
        uses_channels: false,
    };
    for (op, wire) in &family.ops {
        let name = quoted(op);
        let alias = alias(op);
        let out = &mut checks.lines;
        match wire.upstream {
            Upstream::NeoOnly { reason: why } => {
                let _ = writeln!(out, "// {op}: Neo only: {}", reason(why));
            }
            Upstream::Replaces {
                command,
                reason: why,
            } => {
                let _ = writeln!(out, "// {op} replaces {command}: {}", reason(why));
                // Resolves only while upstream still has the command.
                let _ = writeln!(
                    out,
                    "type {alias}_replaces = pw.{}Params",
                    command_stem(command)
                );
                checks.uses_channels = true;
            }
            Upstream::Command(Command {
                name: command,
                adds,
                omits,
                retypes,
                result,
            }) => {
                let stem = command_stem(command);
                let _ = writeln!(out, "// {op}: {command}");
                for (list, keys) in [("adds", adds), ("omits", omits), ("retypes", retypes)] {
                    for (key, why) in keys {
                        let _ = writeln!(out, "//   {list} {key}: {}", reason(why));
                    }
                }
                // A flat input (task 006) is compared as it is, nesting included, so an `options`
                // bag left on an aligned row fails as `neoOnly: 'options'`; a nested one is
                // compared with its bag lifted, as Neo has always sent it.
                let check = match wire.option_nesting {
                    OptionNesting::Flat => "ExactUpstreamCheck",
                    OptionNesting::Nested | OptionNesting::None => "UpstreamCheck",
                };
                let _ = writeln!(
                    out,
                    "type {alias} = Assert<{check}<{name}, {}, pw.{stem}Params, {}, {}, {}>>",
                    wire.input,
                    union(adds),
                    union(omits),
                    union(retypes),
                );
                checks.helpers.extend(["Assert", check]);
                if !wire.option_keys.is_empty() {
                    let _ = writeln!(
                        out,
                        "type {alias}_keys = Assert<KeysCheck<{name}, (typeof {screaming}_OPTION_KEYS)[{name}][number], pw.{stem}Options>>"
                    );
                    checks.helpers.insert("KeysCheck");
                }
                if let Some(why) = result {
                    let _ = writeln!(
                        out,
                        "//   result: {} (no void check: Neo answers more than null on purpose)",
                        reason(why)
                    );
                } else {
                    let _ = writeln!(
                        out,
                        "type {alias}_result = Assert<VoidIsNull<{name}, pw.{stem}Result, {}>>",
                        wire.output
                    );
                    checks.helpers.insert("VoidIsNull");
                }
                checks.uses_channels = true;
            }
        }
    }
    checks
}

fn index_ts(families: &[Family]) -> String {
    let mut out = format!("{HEADER}\n");
    for family in families {
        let pascal = pascal(family.name);
        let screaming = screaming(family.name);
        let _ = writeln!(
            out,
            "import {{\n  {screaming}_OPTION_KEYS,\n  {screaming}_SEND,\n  type {pascal}Inputs,\n  \
             type {pascal}Outputs,\n}} from './{}'",
            family.name
        );
    }
    out.push('\n');
    for family in families {
        let _ = writeln!(out, "export * from './{}'", family.name);
    }
    out.push_str("export * from './common'\n");
    let join = |suffix: &str, screaming_case: bool, separator: &str| -> String {
        let names: Vec<String> = families
            .iter()
            .map(|family| {
                if screaming_case {
                    format!("{}{suffix}", screaming(family.name))
                } else {
                    format!("{}{suffix}", pascal(family.name))
                }
            })
            .collect();
        names.join(separator)
    };
    let _ = writeln!(
        out,
        "\n/**\n * Every op Rust describes, by name: its input after the `call` header. `wire.ts` joins the\n \
         * ops still described by hand.\n */\nexport type GeneratedInputs = {}\n",
        join("Inputs", false, " &\n  ")
    );
    let _ = writeln!(
        out,
        "/** Every op Rust describes, by name: its result. */\nexport type GeneratedOutputs = {}\n",
        join("Outputs", false, " &\n  ")
    );
    let _ = writeln!(
        out,
        "/** The script's option keys of every described op that takes an `options` bag. */\n\
         export const OPTION_KEYS = {{\n  ...{},\n}} as const\n",
        join("_OPTION_KEYS", true, ",\n  ...")
    );
    let _ = writeln!(
        out,
        "/**\n * One typed sender per described op: `send['locator.click'](site, call, {{ target, strict,\n \
         * options }})`.\n */\nexport const send = {{\n  ...{},\n}}",
        join("_SEND", true, ",\n  ...")
    );
    out
}

/// Every file under `dir`, by path relative to it.
fn read_tree(dir: &Path, at: &Path, out: &mut Files) -> io::Result<()> {
    let entries = match fs::read_dir(at) {
        Ok(entries) => entries,
        Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(()),
        Err(error) => return Err(error),
    };
    for entry in entries {
        let path = entry?.path();
        if path.is_dir() {
            read_tree(dir, &path, out)?;
        } else {
            let relative = path.strip_prefix(dir).map_err(io::Error::other)?;
            out.insert(relative.to_owned(), fs::read_to_string(&path)?);
        }
    }
    Ok(())
}

/// Makes `dir` hold exactly `files`, and says what it changed: an empty list when the committed
/// folder already matched.
fn sync(dir: &Path, files: &Files) -> io::Result<Vec<String>> {
    let mut committed = Files::new();
    read_tree(dir, dir, &mut committed)?;
    committed.retain(|path, _| !FOREIGN.iter().any(|foreign| path == Path::new(foreign)));
    let mut changed = Vec::new();
    for (path, text) in files {
        let verb = match committed.get(path) {
            Some(old) if old == text => continue,
            Some(_) => "rewrote",
            None => "wrote",
        };
        let target = dir.join(path);
        if let Some(parent) = target.parent() {
            fs::create_dir_all(parent)?;
        }
        fs::write(&target, text)?;
        changed.push(format!("{verb} {}", path.display()));
    }
    for path in committed.keys().filter(|path| !files.contains_key(*path)) {
        fs::remove_file(dir.join(path))?;
        changed.push(format!("removed {}", path.display()));
        // An emptied `types/` goes too; a folder with files left keeps them.
        if let Some(parent) = dir.join(path).parent()
            && parent != dir
            && fs::read_dir(parent)?.next().is_none()
        {
            fs::remove_dir(parent)?;
        }
    }
    Ok(changed)
}

#[test]
fn tests_that_the_generated_prelude_files_match_the_rust_wire() -> Result<(), Box<dyn Error>> {
    let mut files = render(&families()).map_err(|refusals| refusals.join("\n"))?;
    files.insert("ops.ts".into(), ops_ts()?);
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join(GENERATED);
    let changed = sync(&dir, &files)?;
    assert!(
        changed.is_empty(),
        "{} did not match the Rust wire and has been rewritten; review and commit it:\n  {}",
        dir.display(),
        changed.join("\n  ")
    );
    Ok(())
}

/// The override list is exact: every imported name the generated types print is listed with
/// an example file that exists, and every listed name is still printed.
#[test]
fn tests_that_every_imported_type_is_held_by_an_example_file() -> Result<(), Box<dyn Error>> {
    let files = render(&families()).map_err(|refusals| refusals.join("\n"))?;
    let mut used = BTreeSet::new();
    let mut unlisted = Vec::new();
    for (path, text) in &files {
        for import in imports(text) {
            if IMPORTED
                .iter()
                .any(|entry| entry.module == import.module && entry.name == import.name)
            {
                used.insert(import);
            } else {
                unlisted.push(format!(
                    "{}: import('{}').{}",
                    path.display(),
                    import.module,
                    import.name
                ));
            }
        }
    }
    assert!(
        unlisted.is_empty(),
        "a Rust type prints as an imported name no example file checks; derive its shape, or \
         add it to IMPORTED with the file both sides decode:\n  {}",
        unlisted.join("\n  ")
    );
    for entry in IMPORTED {
        assert!(
            used.contains(&Import {
                module: entry.module.to_owned(),
                name: entry.name.to_owned(),
            }),
            "IMPORTED lists import('{}').{}, which no generated type prints any more",
            entry.module,
            entry.name
        );
        assert!(
            Path::new(env!("CARGO_MANIFEST_DIR"))
                .join(entry.checked_by)
                .is_file(),
            "{} is held by {}, which does not exist",
            entry.name,
            entry.checked_by
        );
    }
    Ok(())
}

#[test]
fn tests_that_imports_are_read_from_either_quote() {
    assert_eq!(
        imports("a: import('../x').Y[], b: import(\"z\").W_2 | null, c: import(x)"),
        [
            Import {
                module: "../x".to_owned(),
                name: "Y".to_owned()
            },
            Import {
                module: "z".to_owned(),
                name: "W_2".to_owned()
            }
        ]
    );
}

#[test]
fn tests_that_names_are_safe_in_a_single_quoted_string() {
    for op in Op::all() {
        let name = op.spec().name;
        assert!(
            name.chars().all(|c| c.is_ascii_alphanumeric() || c == '.'),
            "{name} is written into TypeScript between single quotes and into alias names"
        );
    }
}

/// The layout over hand-built wires, which stand in for the families' route rows.
mod layout {
    use std::any::{self, TypeId};
    use std::error::Error;
    use std::fs;
    use std::path::{Path, PathBuf};

    use neo_playwright::{Command, OpWire, OptionNesting, Upstream, WireType};

    use super::{Family, Files, render, sync};

    fn named<T: 'static>(name: &str) -> WireType {
        WireType {
            name: name.to_owned(),
            file: PathBuf::from(format!("{name}.ts")),
            text: Ok(format!("export type {name} = {{ n: number }};\n")),
            rust: any::type_name::<T>(),
            id: TypeId::of::<T>(),
        }
    }

    fn wire(input: &str, output: &str, types: Vec<WireType>, upstream: Upstream) -> OpWire {
        let references = [input, output]
            .into_iter()
            .map(|reference| reference.trim_end_matches(" | null"))
            .filter(|name| types.iter().any(|named| named.name == *name))
            .map(str::to_owned)
            .collect();
        OpWire {
            input: input.to_owned(),
            output: output.to_owned(),
            references,
            option_keys: Vec::new(),
            option_nesting: OptionNesting::None,
            upstream,
            types,
        }
    }

    fn command(name: &'static str) -> Command {
        Command {
            name,
            adds: &[],
            omits: &[],
            retypes: &[],
            result: None,
        }
    }

    fn file<'f>(files: &'f Files, path: &str) -> &'f str {
        files.get(Path::new(path)).map_or("", String::as_str)
    }

    struct Brand;
    struct HoverInput;
    struct OtherBrand;
    struct TitleInput;

    fn two_families() -> Vec<Family> {
        let hover = wire(
            "HoverInput",
            "null",
            vec![
                named::<HoverInput>("HoverInput"),
                named::<Brand>("PageBrand"),
            ],
            Upstream::Command(command("ElementHandle.hover")),
        );
        let title = wire(
            "TitleInput",
            "string",
            vec![
                named::<TitleInput>("TitleInput"),
                named::<Brand>("PageBrand"),
            ],
            Upstream::NeoOnly {
                reason: "reads the document's title",
            },
        );
        vec![
            Family {
                name: "action",
                ops: vec![("locator.hover", hover)],
            },
            Family {
                name: "locator-handler",
                ops: Vec::new(),
            },
            Family {
                name: "page",
                ops: vec![("page.title", title)],
            },
        ]
    }

    #[test]
    fn tests_that_a_type_two_families_reach_lands_in_common_once() -> Result<(), Box<dyn Error>> {
        let files = render(&two_families()).map_err(|refusals| refusals.join("\n"))?;
        assert_eq!(
            file(&files, "common.ts")
                .matches("export type { PageBrand } from './types/PageBrand'")
                .count(),
            1,
            "a shared type is exported once, from common.ts"
        );
        for family in ["action.ts", "page.ts"] {
            assert!(
                !file(&files, family).contains("export type { PageBrand }"),
                "{family} must not export a shared type too: index.ts exports both files"
            );
        }
        assert!(
            file(&files, "action.ts")
                .contains("export type { HoverInput } from './types/HoverInput'"),
            "a family's own type is exported from its file"
        );
        assert!(
            file(&files, "types/PageBrand.ts").starts_with("export type PageBrand"),
            "each named type keeps the file ts-rs printed"
        );
        Ok(())
    }

    #[test]
    fn tests_that_each_family_file_maps_its_ops_and_checks_each_row() -> Result<(), Box<dyn Error>>
    {
        let files = render(&two_families()).map_err(|refusals| refusals.join("\n"))?;
        let action = file(&files, "action.ts");
        assert!(action.contains("export type ActionInputs = {\n  'locator.hover': HoverInput\n}"));
        assert!(action.contains("export type ActionOutputs = {\n  'locator.hover': null\n}"));
        assert!(
            action.contains(
                "type _locator_hover = Assert<UpstreamCheck<'locator.hover', HoverInput, \
                 pw.ElementHandleHoverParams, never, never, never>>"
            ),
            "{action}"
        );
        assert!(
            action.contains(
                "type _locator_hover_result = Assert<VoidIsNull<'locator.hover', \
                 pw.ElementHandleHoverResult, null>>"
            ),
            "a void command without a result reason is held to null: {action}"
        );
        assert!(action.contains(
            "  'locator.hover': (\n    site: CallSite,\n    call: CallHeader,\n    input: HoverInput,\n    \
             signal?: SignalLike,\n  ): Promise<null> => invoke('locator.hover', site, call, input, signal),"
        ));
        let page = file(&files, "page.ts");
        assert!(page.contains("// page.title: Neo only: reads the document's title"));
        assert!(
            !page.contains("channels'"),
            "a family of Neo-only rows has nothing to compare upstream with"
        );
        let empty = file(&files, "locator-handler.ts");
        assert!(empty.contains("export type LocatorHandlerInputs = {}"));
        assert!(empty.contains("export const LOCATOR_HANDLER_SEND = {}"));
        assert!(
            !empty.contains("import"),
            "a family with nothing described imports nothing: {empty}"
        );
        let index = file(&files, "index.ts");
        assert!(index.contains(
            "export type GeneratedInputs = ActionInputs &\n  LocatorHandlerInputs &\n  PageInputs"
        ));
        assert!(index.contains("export * from './locator-handler'"));
        Ok(())
    }

    #[test]
    fn tests_that_deviations_keys_and_reasons_reach_the_checks() -> Result<(), Box<dyn Error>> {
        let mut drop = wire(
            "DropInput",
            "{ navigation: number } | null",
            vec![named::<HoverInput>("DropInput")],
            Upstream::Command(Command {
                adds: &[("files", "paths or payloads Rust resolves on Neo's disk")],
                omits: &[
                    ("localPaths", "folded into files"),
                    ("streams", "no client streams"),
                ],
                result: Some("the drop's navigation cut"),
                ..command("Frame.drop")
            }),
        );
        drop.option_keys = vec!["force", "it's"];
        let expect = wire(
            "DropInput",
            "null",
            vec![named::<HoverInput>("DropInput")],
            Upstream::Replaces {
                command: "Frame.expect",
                reason: "the matcher model",
            },
        );
        let families = [Family {
            name: "action",
            ops: vec![("locator.drop", drop), ("expect.locator", expect)],
        }];
        let files = render(&families).map_err(|refusals| refusals.join("\n"))?;
        let action = file(&files, "action.ts");
        for line in [
            "//   adds files: paths or payloads Rust resolves on Neo's disk",
            "type _locator_drop = Assert<UpstreamCheck<'locator.drop', DropInput, pw.FrameDropParams, \
             'files', 'localPaths' | 'streams', never>>",
            "  'locator.drop': ['force', 'it\\'s'],",
            "type _locator_drop_keys = Assert<KeysCheck<'locator.drop', \
             (typeof ACTION_OPTION_KEYS)['locator.drop'][number], pw.FrameDropOptions>>",
            "//   result: the drop's navigation cut (no void check",
            "// expect.locator replaces Frame.expect: the matcher model",
            "type _expect_locator_replaces = pw.FrameExpectParams",
        ] {
            assert!(action.contains(line), "missing `{line}` in:\n{action}");
        }
        assert!(
            !action.contains("_locator_drop_result"),
            "a result reason waives the void check"
        );
        Ok(())
    }

    #[test]
    fn tests_that_a_flat_row_is_compared_with_its_nesting() -> Result<(), Box<dyn Error>> {
        let mut click = wire(
            "ClickInput",
            "null",
            vec![named::<HoverInput>("ClickInput")],
            Upstream::Command(command("ElementHandle.click")),
        );
        click.option_keys = vec!["force"];
        click.option_nesting = OptionNesting::Flat;
        let families = [Family {
            name: "action",
            ops: vec![("locator.click", click)],
        }];
        let files = render(&families).map_err(|refusals| refusals.join("\n"))?;
        let action = file(&files, "action.ts");
        assert!(
            action.contains(
                "type _locator_click = Assert<ExactUpstreamCheck<'locator.click', ClickInput, \
                 pw.ElementHandleClickParams, never, never, never>>"
            ),
            "an aligned row's nesting is compared, not lifted: {action}"
        );
        assert!(action.contains(
            "import type { Assert, ExactUpstreamCheck, KeysCheck, VoidIsNull } from '../upstream-check'"
        ));
        assert!(
            action.contains("  'locator.click': ['force'],"),
            "a flat row keeps its option keys"
        );
        Ok(())
    }

    #[test]
    fn tests_that_two_rust_types_under_one_name_are_refused() {
        let families = [Family {
            name: "action",
            ops: vec![
                (
                    "locator.hover",
                    wire(
                        "HoverInput",
                        "null",
                        vec![named::<Brand>("PageBrand")],
                        Upstream::NeoOnly { reason: "x" },
                    ),
                ),
                (
                    "locator.focus",
                    wire(
                        "HoverInput",
                        "null",
                        vec![named::<OtherBrand>("PageBrand")],
                        Upstream::NeoOnly { reason: "x" },
                    ),
                ),
            ],
        }];
        let refusals = render(&families).err().unwrap_or_default();
        assert_eq!(refusals.len(), 1, "{refusals:?}");
        assert!(
            refusals
                .iter()
                .all(|refusal| refusal.contains("both print as TypeScript `PageBrand`")),
            "ts-rs would keep one file and drop the other silently: {refusals:?}"
        );
    }

    #[test]
    fn tests_that_an_untyped_result_is_refused() {
        for output in ["unknown", "JsonValue | null", "any"] {
            let families = [Family {
                name: "page",
                ops: vec![(
                    "page.evaluate",
                    wire(
                        "TitleInput",
                        output,
                        Vec::new(),
                        Upstream::NeoOnly { reason: "x" },
                    ),
                )],
            }];
            let refusals = render(&families).err().unwrap_or_default();
            assert_eq!(
                refusals,
                [format!("page.evaluate: its result prints as `{output}`")],
                "a bare Value answer types nothing"
            );
        }
    }

    #[test]
    fn tests_that_a_stale_folder_is_rewritten_and_reported() -> Result<(), Box<dyn Error>> {
        let dir = tempfile::tempdir()?;
        fs::create_dir_all(dir.path().join("types"))?;
        fs::write(dir.path().join("index.ts"), "// stale\n")?;
        fs::write(dir.path().join("types/Gone.ts"), "export type Gone = 1\n")?;
        let files: Files = [
            (PathBuf::from("index.ts"), "// fresh\n".to_owned()),
            (PathBuf::from("ops.ts"), "// ops\n".to_owned()),
        ]
        .into();
        let changed = sync(dir.path(), &files)?;
        assert_eq!(
            changed,
            ["rewrote index.ts", "wrote ops.ts", "removed types/Gone.ts"]
        );
        assert_eq!(
            fs::read_to_string(dir.path().join("index.ts"))?,
            "// fresh\n"
        );
        assert!(!dir.path().join("types").exists(), "an emptied types/ goes");
        assert!(
            sync(dir.path(), &files)?.is_empty(),
            "a folder that matches is left alone, so the test passes on the second run"
        );
        Ok(())
    }
}
